// AirPods Approvals for Hermes Desktop.
//
// GENERATED by scripts/build.py from src/desktop.js + src/engine.mjs + src/ui.css — edit those.
// Plain ESM loaded uncompiled by the Desktop plugin loader: imports only the SDK and React.
import { Button, Input, ListRow, STATUSBAR_AREAS, PALETTE_AREA, ToggleRow, Codicon, SegmentedControl, atom, host, pluginSettingsHref, useValue } from '@hermes/plugin-sdk'
import { useState } from 'react'
import { jsx, jsxs } from 'react/jsx-runtime'

/*@ENGINE@*/

const PLUGIN_ID = 'airpods-approvals'
const STYLE_ID = 'apa-plugin-style'
const CSS = /*@CSS@*/ ''
const POLL_MS = 2000
const MAX_POLLED_SESSIONS = 12
// Desktop copies the plugin's desktop/ folder here on the Mac, the helper's Swift source included.
const PLUGIN_DIR = '~/.hermes/desktop-plugins/airpods-approvals'
const INSTALLER = `${PLUGIN_DIR}/Install Helper.command`
const SOURCE_URL = 'https://github.com/cineglobe/hermes-airpods-approvals/tree/v1.3.0/desktop/helper'
const INSTALL_MS = 10 * 60 * 1000
const KEY_URL = 'https://aistudio.google.com/apikey'
const MOTION_SETTINGS = 'x-apple.systempreferences:com.apple.preference.security?Privacy_Motion'
const BLUETOOTH_SETTINGS = 'x-apple.systempreferences:com.apple.Bluetooth-Settings.extension'

const $state = atom({ helper: 'off', output: null, motion: 'undecided', motionAsked: false, motionDenied: false, beats: 0, listening: false, missed: 0, asking: null, last: null, geminiKey: false, test: '' })
const $settings = atom({ ...DEFAULT_SETTINGS })

let plugin = null
let link = null
let coordinator = null

// ── voice calls (Gemini Live) ───────────────────────────────────────────────────────────────────
// Plugins talk through window events: `hermes:voice-call` says which session a call is handling and
// whether its voice is speaking. While it is, the call asks and this plugin only opens the gesture
// window, then reports the answer with `hermes:approval-answered`.

let call = { active: false, sessionId: null, speaking: false }

function hearCall(event) {
  const detail = (event && event.detail) || {}
  call = { active: Boolean(detail.active), sessionId: detail.sessionId || null, speaking: Boolean(detail.active && detail.speaking) }
}

const CALL_QUIET_MS = 600
const CALL_START_MS = 8000
const CALL_LONGEST_MS = 25000

// Resolves once the call's voice has spoken and gone quiet, or soon if it never starts.
function waitForCallTurn() {
  return new Promise(resolve => {
    const began = Date.now()
    let spoke = false
    let quietSince = 0
    const timer = setInterval(() => {
      const now = Date.now()
      let done = !call.active || now - began > CALL_LONGEST_MS || (!spoke && now - began > CALL_START_MS)
      if (call.speaking) {
        spoke = true
        quietSince = 0
      } else if (spoke) {
        quietSince = quietSince || now
        done = done || now - quietSince >= CALL_QUIET_MS
      }
      if (done) {
        clearInterval(timer)
        resolve()
      }
    }, 100)
  })
}

function voiceCall(sessionId) {
  return call.active && sessionId && call.sessionId === sessionId ? { waitForTurn: waitForCallTurn } : null
}

function announceAnswer(detail) {
  window.dispatchEvent(new CustomEvent('hermes:approval-answered', { detail }))
}

let gesturesSaid = null

// Tells a call whether it can offer "nod or shake".
function announceGestures(force = false) {
  const state = $state.get()
  const ready = Boolean($settings.get().enabled && state.helper === 'ready' && state.output && !state.motionDenied)
  if (!force && ready === gesturesSaid) return
  gesturesSaid = ready
  window.dispatchEvent(new CustomEvent('hermes:airpods-gestures', { detail: { source: 'airpods-approvals', ready } }))
}

function patch(values) {
  $state.set({ ...$state.get(), ...values })
  if (link) announceGestures()
}

function saveSettings(values) {
  const next = { ...$settings.get(), ...values }
  $settings.set(next)
  plugin.storage.set('settings', next)
  announceGestures()
}

function randomHex(bytes) {
  return hex(crypto.getRandomValues(new Uint8Array(bytes)))
}

async function sign(secret, text) {
  const encoder = new TextEncoder()
  const key = await crypto.subtle.importKey('raw', encoder.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign'])
  return hex(new Uint8Array(await crypto.subtle.sign('HMAC', key, encoder.encode(text))))
}

function pairingToken() {
  return plugin.storage.get('token', '')
}

// Connect makes the token here, starts the helper by opening its app, and offers the token over the
// local socket. The helper takes it only if it has never been paired or Pair Again is open.
function ensureToken() {
  if (!pairingToken()) plugin.storage.set('token', randomHex(32))
}

async function connectHelper() {
  ensureToken()
  patch({ helper: 'connecting' })
  link.pairSoon()
  link.connect()
  await plugin.os.openExternal(HELPER_APP)
  plugin.setTimeout(() => {
    if (!link.connected && $state.get().helper === 'connecting') patch({ helper: link.refused ? 'refused' : 'missing' })
  }, 12000)
}

// Install opens the bundled installer in Terminal, which builds the helper from the source beside it
// and starts it. Pairing stays open meanwhile, so the plugin connects the moment the helper is up.
async function installHelper() {
  ensureToken()
  patch({ helper: 'installing' })
  link.pairSoon(Date.now(), INSTALL_MS)
  link.connect()
  if (!(await plugin.os.openExternal(INSTALLER))) {
    patch({ helper: 'missing' })
    return
  }
  plugin.setTimeout(() => {
    if (!link.connected && $state.get().helper === 'installing') patch({ helper: 'off' })
  }, INSTALL_MS)
}

function syncLink() {
  const status = link.status || {}
  const current = $state.get().helper
  patch({
    helper: link.connected ? 'ready' : link.refused ? 'refused' : current === 'connecting' || current === 'installing' ? current : pairingToken() ? 'waiting' : 'off',
    output: status.output || null,
    motionDenied: Boolean(status.motionDenied),
    motion: status.motion || (status.motionDenied ? 'denied' : 'undecided'),
    geminiKey: Boolean(status.geminiKey)
  })
}

function syncCoordinator() {
  const item = coordinator.current
  patch({
    asking: item ? item.kind : null,
    last: coordinator.last,
    ...(item ? {} : { beats: 0, listening: false })
  })
}

function hearProgress(message) {
  const state = $state.get()
  if (message.state === 'listening') patch({ listening: true, beats: 0 })
  else if (message.state === 'beat') patch({ beats: message.beats })
  else if (message.state === 'missed') patch({ beats: 0, missed: state.missed + 1 })
  else if (message.state === 'confirm') patch({ listening: false, beats: 0 })
}

// ── hearing Hermes ──────────────────────────────────────────────────────────────────────────────

function hearEvent(event) {
  if (!event || !event.session_id || !link.connected || !(link.status.geminiKey || voiceCall(event.session_id))) return
  const payload = event.payload || {}
  if (event.type === 'approval.request') {
    coordinator.offerApproval(event.session_id, { ...payload, request_id: payload.request_id || payload.prompt_id })
  } else if (event.type === 'clarify.request') {
    const questions = Array.isArray(payload.questions)
      ? payload.questions
      : [{ qid: payload.prompt_id, question: payload.question, choices: payload.choices, multi_select: payload.multi_select }]
    coordinator.offerQuestion(event.session_id, payload.prompt_id || payload.request_id, { questions })
  }
}

// Events are the fast path. This poll also catches prompts from sessions Desktop has not opened,
// and notices when a prompt was answered on screen.
let polling = false

async function poll() {
  if (polling || !$settings.get().enabled || !link.connected || !(link.status.geminiKey || call.active)) return
  polling = true
  try {
    const focused = host.state.focusedSessionId.get()
    const reply = await host.request('session.active_list', { current_session_id: focused || null }, 8000)
    const sessions = ((reply && reply.sessions) || []).slice(-MAX_POLLED_SESSIONS)
    await Promise.all(
      sessions.map(async session => {
        const answer = await host.request('approval.pending', { session_id: session.id }, 5000).catch(() => null)
        if (!answer) return
        const pending = answer.approvals || []
        coordinator.reconcile(session.id, pending)
        pending.forEach(request => coordinator.offerApproval(session.id, request))
      })
    )
  } catch {
    // The connection may be down; the next poll tries again.
  } finally {
    polling = false
  }
}

// A practice run: it uses the real helper and gestures, and never touches Hermes.
async function tryGesture() {
  patch({ test: 'Listening', beats: 0 })
  const { listenSeconds, confirmApprovals } = $settings.get()
  const result = await link.ask({
    id: `try-${randomHex(4)}`,
    mode: 'gesture',
    text: 'Nod to say yes, or shake to say no.',
    listenSeconds,
    confirm: confirmApprovals
  })
  const words = { yes: 'You nodded', no: 'You shook your head' }
  const reasons = { ...REASONS, timeout: 'No gesture heard' }
  patch({ test: words[result.answer] || reasons[result.reason] || 'Stopped', beats: 0, listening: false })
}

// ── interface ───────────────────────────────────────────────────────────────────────────────────

function Beats({ large }) {
  const { beats, missed } = useValue($state)
  return jsx('span', {
    className: `apa-beats${large ? ' apa-beats--large' : ''}${missed % 2 ? ' apa-beats--miss' : ''}`,
    'aria-label': `${beats} of 3 beats`,
    children: [1, 2, 3].map(n => jsx('span', { className: n <= beats ? 'apa-beat apa-beat--on' : 'apa-beat' }, n))
  })
}

function StatusChip() {
  const state = useValue($state)
  const settings = useValue($settings)
  if (!settings.enabled) return null
  const title = state.helper === 'ready' ? (state.output ? `AirPods Approvals: ${state.output}` : 'AirPods Approvals: connect your AirPods') : 'AirPods Approvals: helper not connected'
  return jsx('button', {
    className: 'apa-chip',
    onClick: () => host.navigate(pluginSettingsHref(PLUGIN_ID)),
    title,
    type: 'button',
    children: state.listening
      ? jsx(Beats, {})
      : [jsx(Codicon, { name: state.helper === 'ready' && state.output ? 'unmute' : 'mute', size: '0.8rem' }, 'i')]
  })
}

function helperText(state) {
  if (state.helper === 'missing') return 'Helper not found. Install builds it on this Mac.'
  if (state.helper === 'installing') return 'Building in Terminal. This takes about a minute.'
  if (state.helper === 'refused') return 'Choose Pair Again in the menu bar, then Connect'
  if (state.helper === 'connecting') return 'Connecting'
  if (state.helper === 'waiting') return 'Helper not running'
  if (state.helper === 'off') return 'Head tracking needs a small Mac app. Install builds it here from its source, in Terminal. Nothing is downloaded.'
  return 'Installed and running'
}

const REASONS = {
  unavailable: 'AirPods not ready',
  noMotion: 'No head movement. Are both AirPods in?',
  noKey: 'Add a Gemini key',
  noVoice: "Gemini didn't answer",
  lost: 'AirPods lost'
}

function outcomeText(last) {
  if (!last) return 'Nothing asked yet'
  const text = { approved: 'Approved', denied: 'Denied', answered: `Answered: ${last.detail}`, read: 'Read aloud', stale: 'Already answered on screen', call: 'Left to Gemini Live', error: 'Could not send that answer' }
  if (last.outcome === 'unanswered') return `${REASONS[last.detail] || 'No answer given'}, left on screen`
  return text[last.outcome] || last.outcome
}

// The key goes straight to the helper, which keeps it in the Keychain. Desktop never stores it.
function KeyRow({ state }) {
  const [draft, setDraft] = useState('')
  const linked = state.helper === 'ready'
  if (state.geminiKey) {
    return jsx(ListRow, {
      title: 'Gemini key',
      description: 'Saved',
      action: jsx(Button, { onClick: () => link.send({ type: 'setKey', key: '' }), size: 'sm', type: 'button', variant: 'outline', children: 'Remove' })
    })
  }
  const save = () => {
    if (!draft.trim()) return
    link.send({ type: 'setKey', key: draft.trim() })
    setDraft('')
  }
  return jsx(ListRow, {
    title: 'Gemini key',
    description: 'Gemini reads each request aloud in your AirPods. A free key from Google AI Studio is enough.',
    action: jsxs('span', {
      className: 'apa-key',
      children: [
        jsx(Button, { onClick: () => void plugin.os.openExternal(KEY_URL), size: 'sm', type: 'button', variant: 'ghost', children: 'Get a free key' }),
        jsx(Input, {
          'aria-label': 'Gemini API key',
          autoComplete: 'off',
          disabled: !linked,
          onChange: event => setDraft(event.target.value),
          onKeyDown: event => event.key === 'Enter' && save(),
          placeholder: 'Paste key',
          spellCheck: false,
          type: 'password',
          value: draft
        }),
        jsx(Button, { disabled: !linked || !draft.trim(), onClick: save, size: 'sm', type: 'button', variant: 'default', children: 'Save' })
      ]
    })
  })
}

// Source opens the helper's code for this version, so people can read what Install builds.
function HelperActions({ state }) {
  const paired = state.helper === 'waiting' || state.helper === 'refused' || state.helper === 'connecting'
  const installing = state.helper === 'installing'
  return jsxs('span', {
    className: 'apa-helper',
    children: [
      jsx(Button, { onClick: () => void plugin.os.openExternal(SOURCE_URL), size: 'sm', type: 'button', variant: 'ghost', children: 'Source' }),
      paired
        ? jsx(Button, { onClick: () => void connectHelper(), size: 'sm', type: 'button', variant: 'default', children: 'Connect' })
        : jsx(Button, { disabled: installing, onClick: () => void installHelper(), size: 'sm', type: 'button', variant: 'default', children: installing ? 'Installing' : 'Install' })
    ]
  })
}

// Motion access is asked here, after saying why, so macOS's prompt never arrives mid-question.
function MotionRow({ state }) {
  if (state.motion === 'allowed') return jsx(ListRow, { title: 'Motion access', description: 'Allowed' })
  if (state.motion === 'denied') {
    return jsx(ListRow, {
      title: 'Motion access',
      description: 'Turned off. Turn on Hermes AirPods in Privacy & Security, under Motion & Fitness.',
      action: jsx(Button, { onClick: () => void plugin.os.openExternal(MOTION_SETTINGS), size: 'sm', type: 'button', variant: 'outline', children: 'Open Settings' })
    })
  }
  const allow = () => {
    patch({ motionAsked: true })
    link.send({ type: 'requestMotion' })
    // The helper stops asking after two minutes; Allow comes back if the prompt was dismissed.
    plugin.setTimeout(() => patch({ motionAsked: false }), 125000)
  }
  return jsx(ListRow, {
    title: 'Motion access',
    description: state.motionAsked
      ? 'Choose Allow in the macOS prompt.'
      : 'To see a nod or a shake, the helper reads your head movement from your AirPods. macOS asks once. It only reads while Hermes is asking you something, and nothing leaves this Mac.',
    action: jsx(Button, { disabled: state.motionAsked, onClick: allow, size: 'sm', type: 'button', variant: 'default', children: 'Allow' })
  })
}

function AirPodsRow({ state }) {
  if (state.output) return jsx(ListRow, { title: 'AirPods', description: `Connected: ${state.output}` })
  return jsx(ListRow, {
    title: 'AirPods',
    description: 'Put them in and connect them to this Mac.',
    action: jsx(Button, { onClick: () => void plugin.os.openExternal(BLUETOOTH_SETTINGS), size: 'sm', type: 'button', variant: 'outline', children: 'Bluetooth' })
  })
}

// Set up runs as steps: each one appears once the one before it is done.
function SetupRows({ state, ready }) {
  const rows = [jsx(ListRow, { title: 'Helper', description: helperText(state), action: state.helper === 'ready' ? null : jsx(HelperActions, { state }) }, 'helper')]
  if (state.helper !== 'ready') return rows
  rows.push(jsx(KeyRow, { state }, 'key'))
  if (!state.geminiKey) return rows
  rows.push(jsx(MotionRow, { state }, 'motion'))
  if (state.motion !== 'allowed') return rows
  rows.push(jsx(AirPodsRow, { state }, 'airpods'))
  if (!state.output) return rows
  rows.push(
    jsx(ListRow, {
      title: 'Try it',
      description: state.test || 'Three quick beats: nod or shake',
      action: jsxs('span', {
        className: 'apa-try',
        children: [jsx(Beats, { large: true }), jsx(Button, { disabled: !ready || Boolean(state.asking), onClick: () => void tryGesture(), size: 'sm', type: 'button', variant: 'outline', children: 'Start' })]
      })
    }, 'try')
  )
  return rows
}

function SettingsPage() {
  const state = useValue($state)
  const settings = useValue($settings)
  const ready = state.helper === 'ready' && Boolean(state.output) && state.motion === 'allowed' && state.geminiKey
  return jsxs('div', {
    children: [
      ...SetupRows({ state, ready }),
      jsx(ListRow, { title: 'Last request', description: outcomeText(state.last) }),
      jsx(ToggleRow, { checked: settings.enabled, label: 'Answer with my head', onChange: on => saveSettings({ enabled: on }) }),
      jsx(ToggleRow, { checked: settings.confirmApprovals, label: 'Nod twice to approve', description: 'A second round before anything runs.', onChange: on => saveSettings({ confirmApprovals: on }) }),
      jsx(ToggleRow, { checked: settings.questions, label: 'Read questions aloud', onChange: on => saveSettings({ questions: on }) }),
      jsx(ListRow, {
        title: 'Time to answer',
        action: jsx(SegmentedControl, {
          onChange: value => saveSettings({ listenSeconds: Number(value) }),
          options: [{ id: '5', label: '5s' }, { id: '8', label: '8s' }, { id: '12', label: '12s' }],
          value: String(settings.listenSeconds)
        })
      })
    ]
  })
}

// ── registration ────────────────────────────────────────────────────────────────────────────────

export default {
  id: PLUGIN_ID,
  name: 'AirPods Approvals',
  description: 'Hear approvals in your AirPods and answer with a nod or a shake.',
  register(ctx) {
    plugin = ctx
    if (!document.getElementById(STYLE_ID)) {
      const style = document.createElement('style')
      style.id = STYLE_ID
      style.textContent = CSS
      document.head.appendChild(style)
      ctx.onDispose(() => style.remove())
    }

    $settings.set({ ...DEFAULT_SETTINGS, ...ctx.storage.get('settings', {}) })

    link = new HelperLink({
      createSocket: url => new WebSocket(url),
      token: pairingToken,
      sign,
      nonce: () => randomHex(16),
      onChange: syncLink,
      setTimer: (fn, ms) => ctx.setTimeout(fn, ms)
    })
    link.progress = hearProgress

    coordinator = new Coordinator({
      rpc: (method, params, timeout) => host.request(method, params, timeout),
      link,
      settings: () => $settings.get(),
      newId: () => randomHex(8),
      onChange: syncCoordinator,
      voiceCall,
      announce: announceAnswer
    })

    ctx.addEventListener(window, 'hermes:voice-call', hearCall)
    ctx.addEventListener(window, 'hermes:airpods-gestures-query', () => announceGestures(true))
    window.dispatchEvent(new CustomEvent('hermes:voice-call-query'))
    ctx.onDispose(() => window.dispatchEvent(new CustomEvent('hermes:airpods-gestures', { detail: { source: 'airpods-approvals', ready: false } })))

    ctx.onEvent('*', hearEvent)
    ctx.setInterval(() => void poll(), POLL_MS)
    ctx.setInterval(() => link.send({ type: 'status' }), POLL_MS)
    ctx.onDispose(() => link.close())

    ctx.registerMany([
      { id: 'status', area: STATUSBAR_AREAS.right, order: 112, render: () => jsx(StatusChip, {}) },
      { id: 'cmd-try', area: PALETTE_AREA, data: { id: 'airpods-approvals.settings', label: 'AirPods Approvals: Open settings', keywords: ['airpods', 'nod', 'approve'], run: () => host.navigate(pluginSettingsHref(PLUGIN_ID)) } }
    ])
    ctx.registerSettingsPage?.({ id: 'settings', title: 'AirPods Approvals', icon: 'unmute', render: () => jsx(SettingsPage, {}) })

    // Once paired, Desktop starts the helper itself. Only the first launch needs Connect.
    if (pairingToken()) {
      link.connect()
      ctx.setTimeout(() => {
        if (!link.connected) void ctx.os.openExternal(HELPER_APP)
      }, 1500)
    }
  }
}
